con=sqlite3.connect(P/'nutrition.sqlite')
for table,cols,data in [('observations',headers,rows),('sources',['source_id','url','description'],sources),('products',['product','name'],products)]:
 with open(P/(table+'.csv'),'w',newline='',encoding='utf-8') as f: w=csv.writer(f);w.writerow(cols);w.writerows(data)
 con.execute('drop table if exists '+table); con.execute('create table '+table+' ('+','.join(c+(' REAL' if c in ['price_per_pack','pack_kg','quantity_mt','purchase_value','price_per_kg'] else ' INTEGER' if c in ['year','page'] else ' TEXT') for c in cols)+')');con.executemany('insert into '+table+' values ('+','.join('?' for c in cols)+')',data)
con.commit();con.close();print(len(rows),Counter(r[6] for r in rows))
with sqlite3.connect(P/'nutrition.sqlite') as con:
 con.execute('drop table if exists historical_milestones')
 con.execute('create table historical_milestones(year integer,event text,source_id text,evidence_status text)')
 with open(P/'historical_milestones.csv',encoding='utf-8') as f:
  reader=csv.reader(f);next(reader);con.executemany('insert into historical_milestones values (?,?,?,?)',reader)
